# Agent node functions — generated by graphical-agents from the Graph IR (tool_workflow).

from langchain.agents import create_agent
from langchain.chat_models import init_chat_model

try:
    from .agent_tools import count_sentences, run_tool_agent
except ImportError:
    from agent_tools import count_sentences, run_tool_agent
try:
    from .state import WorkflowState
except ImportError:
    from state import WorkflowState


def summarize(state: WorkflowState) -> dict:
    model = init_chat_model("google_genai:gemini-flash-latest")
    prompt = f"Summarize the article in one sentence. Before answering, call the count_sentences tool on your summary and make sure it returns 1.\n\nInput:\n{state['fetch_data_output'].model_dump_json()}"
    agent = create_agent(
        model,
        tools=[count_sentences],
    )
    return {"summarize_output": run_tool_agent(agent, prompt)}
